<div class="section-heading"><div><h2>Project analytics</h2><p class="muted">Real work-item state, recorded effort and progress history.</p></div><span class="badge">No sample data</span></div><div class="work-stats"><?php foreach([['Work items',$analytics['stats']['total']],['Completed',$analytics['stats']['completed']],['Overdue',$analytics['stats']['overdue']],['Tracked time',number_format($analytics['minutes']/60,1).' h']] as [$label,$count]): ?><section class="card"><span><?= e($label) ?></span><strong><?= e($count) ?></strong></section><?php endforeach; ?></div>
<div class="two-col"><section class="card"><h2>Workflow distribution</h2><?php if($analytics['stats']['total']): ?><?= chart('doughnut',array_column($analytics['byState'],'name'),[['label'=>'Work items','data'=>array_column($analytics['byState'],'total'),'backgroundColor'=>array_column($analytics['byState'],'color')]],['cutout'=>'68%']) ?><?php else: ?><div class="empty"><h3>No work items yet.</h3><p>Your workflow chart appears after creating work items.</p></div><?php endif; ?></section><section class="card"><h2>Priority breakdown</h2><?php if($analytics['byPriority']): ?><?= chart('bar',array_map(fn($row)=>WorkService::PRIORITIES[$row['priority']],$analytics['byPriority']),[['label'=>'Work items','data'=>array_column($analytics['byPriority'],'total'),'backgroundColor'=>'#3688ff']],['scales'=>['y'=>['beginAtZero'=>true,'ticks'=>['precision'=>0]]]]) ?><?php else: ?><div class="empty"><p>No priority data yet.</p></div><?php endif; ?></section></div>
<section class="card"><h2>Progress over time</h2><?php if($analytics['history']): ?><?= chart('line',array_column($analytics['history'],'day'),[['label'=>'Total work items','data'=>array_column($analytics['history'],'total'),'borderColor'=>'#94a3b8'],['label'=>'Completed','data'=>array_column($analytics['history'],'completed'),'borderColor'=>'#22b37e']],['scales'=>['y'=>['beginAtZero'=>true,'ticks'=>['precision'=>0]]]]) ?><p class="footnote">Daily snapshots are recorded from real changes. Dates before your first update are not filled with estimates.</p><?php else: ?><p class="muted">Progress snapshots appear as work items change.</p><?php endif; ?></section>
<section class="card"><h2>Assignee workload</h2><?php if(!$analytics['byPerson']): ?><p class="muted">Assign work items to people to see their workload.</p><?php else:foreach($analytics['byPerson'] as $person): ?><article class="work-workload"><span class="work-avatar"><?= e(mb_substr($person['name'],0,1)) ?></span><strong><?= e($person['name']) ?></strong><span><?= e($person['total']) ?> assigned · <?= e($person['completed']) ?> completed</span></article><?php endforeach; ?><p class="footnote">A work item assigned to more than one person is counted for each assignee.</p><?php endif; ?></section>
